const PARTNER_COUPONS = {
  'santander_clientes': 'recCBAWUlgKzkHTan',
  'binance_inversores_clientes': 'recD1vbGsfa4uOP76',
  'degiro_clientes': 'recgrauiLb9oZbsTT',
  'okx_720_clientes': 'recCPVC55tS3CtLTM',
  'bitvavo_clientes': 'reczE9I3qJeH3HpHO',
};

const partnerId = $('Webhook_Upsert_Expediente').item.json.body.partner || '';
const coupon = PARTNER_COUPONS[partnerId] || null;

return [{
  json: {
    ...$input.first().json,
    coupon: coupon ? [coupon] : []
  }
}];

// Detectar tipo de usuario
const items = $input.all();
// Datos que vienen del nodo Search Records (Airtable)
const inputData = items[0]?.json || {};

// CORRECCIÓN: Referencia directa al nodo Webhook para sacar datos originales
const webhookData = $('Webhook_Upsert_Expediente').item.json || {};

const hoy = new Date();
const añoActual = hoy.getFullYear();
const mesActual = hoy.getMonth() + 1;
const campañaActual = mesActual >= 7 ? añoActual + 1 : añoActual;

const datosBase = {
  chat_history: webhookData.chat_history || '',
  user_id: webhookData.user_id || ''
};

// Sin registro en Airtable = nuevo
if (!inputData.id) {
  return [{ json: { ...datosBase, tipo_usuario: 'nuevo', campaña_actual: `Renta ${campañaActual}` } }];
}

const registro = inputData;

// CAMPOS ACTUALIZADOS según nuevo esquema
const statusTraza = registro.status_traza || '';
const trazaHechaHasta = registro.traza_hecha_hasta || null;

// VALIDACIÓN DE PAGO: cualquiera de las dos condiciones
const facturaPagadaCheckbox = registro['Factura pagada trazabilidad'] === true;
const paymentStatusArray = registro['Payment_Status (from Checkout_Linked)'] || [];
const paymentStatusPaid = paymentStatusArray.includes('Paid');

// Pagado si cualquiera es true
const facturaPagada = facturaPagadaCheckbox || paymentStatusPaid;

// Proceso pagado en curso
const esDescartado = statusTraza.toLowerCase().includes('descartado');
if (facturaPagada && statusTraza !== 'Presentado' && !esDescartado) {
  return [{ json: {
    ...datosBase,
    tipo_usuario: 'proceso_pagado_en_curso',
    status_actual: statusTraza,
    exchanges_anteriores: registro.exchanges || [],
    redes_anteriores: registro.blockchains || [],
    cold_wallets_anteriores: registro.cold_wallets || [],
    campaña_actual: `Renta ${campañaActual}`
  }}];
}

// Cliente recurrente
if (statusTraza === 'Presentado' && trazaHechaHasta) {
  const añoTraza = parseInt(trazaHechaHasta, 10);
  const ultimaCampaña = añoTraza + 1;

  return [{ json: {
    ...datosBase,
    tipo_usuario: 'recurrente',
    ultima_campaña_completada: `Renta ${ultimaCampaña}`,
    campaña_actual: `Renta ${campañaActual}`,
    año_inicio: registro.entrada_en_cripto || 'No registrado',
    exchanges_anteriores: registro.exchanges || [],
    redes_anteriores: registro.blockchains || [],
    cold_wallets_anteriores: registro.cold_wallets || [],
    tenia_defi: registro.defi === 'Sí' || registro.tiene_defi === true
  }}];
}

// Usuario nuevo (default)
return [{ json: { ...datosBase, tipo_usuario: 'nuevo', campaña_actual: `Renta ${campañaActual}` } }];
